// ===============================================================================
// DAEMIND SRE - AUDITOR CONTÁBIL DE OVER-ATTRIBUTION DE ADS
// ===============================================================================
const j = $json;

const caixaReal = parseFloat(j.faturamento_caixa_real || 0);
const investimentoAds = parseFloat(j.investimento_ads_total || 0);
const receitaPixel = parseFloat(j.receita_reportada_pixel || 0);
const pedidosPagos = parseInt(j.pedidos_pagos || 0, 10);

const roasCaixa = investimentoAds > 0 ? (caixaReal / investimentoAds) : 0;
const roasPixel = investimentoAds > 0 ? (receitaPixel / investimentoAds) : 0;

const diferencaAbsoluta = receitaPixel - caixaReal;
const overAttributionPct = caixaReal > 0 ? ((receitaPixel - caixaReal) / caixaReal) * 100 : 0;
const isOverAttributed = overAttributionPct >= 20.0;

const emoji = isOverAttributed ? '🚨' : '✅';
const statusAlerta = isOverAttributed ? 'ALERTA_SOBREATRIBUICAO' : 'ROAS_SAUDAVEL';

const msg = `${emoji} *DAEMIND SRE - AUDITORIA DE ADS vs CAIXA REAL* ${emoji}\n\n📅 *Data:* ${j.data_referencia}\n💰 *Caixa Real (Banco):* R$ ${caixaReal.toFixed(2)} (${pedidosPagos} pedidos pagos)\n📊 *Receita Pixel (Gerenciadores Ads):* R$ ${receitaPixel.toFixed(2)}\n🎯 *Investimento em Ads:* R$ ${investimentoAds.toFixed(2)}\n\n📈 *ROAS Real Caixa:* ${roasCaixa.toFixed(2)}x\n📉 *ROAS Pixel Reportado:* ${roasPixel.toFixed(2)}x\n\n${isOverAttributed ? `⚠️ *Discrepância / Over-Attribution:* +${overAttributionPct.toFixed(1)}% (R$ ${diferencaAbsoluta.toFixed(2)} inflados pelas plataformas)` : '✨ Métricas de atribuição alinhadas com o caixa real.'}`;

return [{
  json: {
    ...j,
    caixa_real: caixaReal,
    investimento_ads: investimentoAds,
    receita_pixel: receitaPixel,
    roas_caixa: roasCaixa,
    roas_pixel: roasPixel,
    over_attribution_pct: overAttributionPct,
    is_over_attributed: isOverAttributed,
    relatorio_whatsapp: msg
  }
}];
